    /// The months that have an awards ceremony, newest first. The first one is the
    /// ceremony of the current month.
    static func awardMonths(now: Date) -> [String] {
        let calendar = Calendar(identifier: .gregorian)
        let current = calendar.component(.month, from: now)
        let year = calendar.component(.year, from: now)
        let previousMonth = current == 1 ? 12 : current - 1
        let previousYear = current == 1 ? year - 1 : year
        return [
            String(format: "%04d-%02d", year, current),
            String(format: "%04d-%02d", previousYear, previousMonth),
        ]
    }

    /// The winner of every award of a ceremony month.
    static func awardWinners(month: String, points: [String: Int]) -> [AwardKey: [String]] {
        let ranked = points.sorted { $0.value > $1.value }
        let leader = ranked.first?.key ?? currentUserID
        let last = ranked.last?.key ?? currentUserID
        let stats = self.stats
        let mostGoals = ranked.max { (stats[$0.key]?.goals ?? 0) < (stats[$1.key]?.goals ?? 0) }?.key ?? leader
        let mostRefCalls = ranked.max { (stats[$0.key]?.noGoalCalls ?? 0) < (stats[$1.key]?.noGoalCalls ?? 0) }?.key ?? leader
        let biggestClimb = ranked.max { (stats[$0.key]?.comeback ?? 0) < (stats[$1.key]?.comeback ?? 0) }?.key ?? leader
        let mostFirst = ranked.max { (stats[$0.key]?.firstToScore ?? 0) < (stats[$1.key]?.firstToScore ?? 0) }?.key ?? leader

        if month.hasSuffix("-10") {
            // The ceremony of October was won by Lee; Alex took the golden boot.
            return [
                .playerOfTheMonth: ["demo-user-lee"],
                .goldenBoot: [currentUserID],
                .toughestRef: ["demo-user-jo"],
                .comebackKid: ["demo-user-sam"],
                .firstToScore: ["demo-user-mika"],
                .woodenSpoon: [last],
            ]
        }
        return [
            .playerOfTheMonth: [leader],
            .goldenBoot: [mostGoals],
            .toughestRef: [mostRefCalls],
            .comebackKid: [biggestClimb],
            .firstToScore: [mostFirst],
            .woodenSpoon: [last],
        ]
    }

    /// The value of an award for a member.
    static func awardValue(_ award: AwardKey, userID: String, points: Int) -> Int {
        let stats = self.stats[userID]
        return switch award {
        case .playerOfTheMonth: points
        case .goldenBoot: stats?.goals ?? 0
        case .toughestRef: stats?.noGoalCalls ?? 0
        case .comebackKid: stats?.comeback ?? 0
        case .firstToScore: stats?.firstToScore ?? 0
        case .woodenSpoon: points
        }
    }

    /// The description of a fixture, in the tone of the club.
    static func description(for title: String, difficulty: Difficulty) -> String {
        switch difficulty {
        case .easy:
            return "“\(title)” — less than an hour, one photo is enough."
        case .medium:
            return "“\(title)” needs a bit of planning, but it is doable before Sunday night."
        case .hard:
            return "“\(title)” is the big one of the week. Take your time and make it count."
        }
    }
